   484→  /**
   485→   * Split command chain into individual commands
   486→   */
   487→  splitCommandChain(command) {
   488→    // Simple splitting on && ; ||
   489→    // This is basic - doesn't handle complex quoting, but good enough for basic validation
   490→    const commands = [];
   491→    let current = "";
   492→    let inQuotes = false;
   493→    let quoteChar = "";
   494→
   495→    for (let i = 0; i < command.length; i++) {
   496→      const char = command[i];
   497→      const nextChar = command[i + 1];
   498→
   499→      // Handle quotes
   500→      if ((char === '"' || char === "'") && !inQuotes) {
   501→        inQuotes = true;
   502→        quoteChar = char;
   503→        current += char;
   504→      } else if (char === quoteChar && inQuotes) {
   505→        inQuotes = false;
   506→        quoteChar = "";
   507→        current += char;
   508→      } else if (inQuotes) {
   509→        current += char;
   510→      } else if (char === "&" && nextChar === "&") {
   511→        commands.push(current.trim());
   512→        current = "";
   513→        i++; // skip next &
   514→      } else if (char === "|" && nextChar === "|") {
   515→        commands.push(current.trim());
   516→        current = "";
   517→        i++; // skip next |
   518→      } else if (char === ";") {
   519→        commands.push(current.trim());
   520→        current = "";
   521→      } else {
   522→        current += char;
   523→      }
   524→    }
   525→
   526→    if (current.trim()) {
   527→      commands.push(current.trim());
   528→    }
   529→
   530→    return commands.filter((cmd) => cmd.length > 0);
   531→  }
